<?php require_once __DIR__.'/inc/functions.php'; if(is_logged_in()) redirect('/students/index.php'); $errors=[]; $username=''; $email=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf(); $username=trim($_POST['username']??''); $email=trim($_POST['email']??''); $password=$_POST['password']??''; $confirm=$_POST['confirm_password']??''; if(mb_strlen($username)<3||mb_strlen($username)>100)$errors[]='اسم المستخدم يجب أن يتراوح بين 3 و100 محرف.'; if(!valid_email($email)||mb_strlen($email)>100)$errors[]='أدخل بريداً إلكترونياً صحيحاً.'; if(strlen($password)<8)$errors[]='كلمة المرور يجب ألا تقل عن 8 محارف.'; if($password!==$confirm)$errors[]='تأكيد كلمة المرور غير مطابق.'; if(!$errors){$q=db()->prepare('SELECT id FROM users WHERE username=? OR email=?');$q->execute([$username,$email]);if($q->fetch())$errors[]='اسم المستخدم أو البريد الإلكتروني مستخدم مسبقاً.';} if(!$errors){$q=db()->prepare('INSERT INTO users(username,email,password) VALUES(?,?,?)');$q->execute([$username,$email,password_hash($password,PASSWORD_DEFAULT)]);flash('success','تم إنشاء الحساب. يمكنك تسجيل الدخول الآن.');redirect('/login.php');}} $title='إنشاء حساب';require __DIR__.'/inc/header.php'; ?>
<div class="form-card auth-card"><div class="form-heading"><span class="form-symbol">+</span><span class="eyebrow">نظام تسجيل الطلاب</span><h1>أنشئ حسابك</h1><p>ابدأ بإدارة سجلات الطلاب من خلال حسابك الخاص.</p></div><?php if($errors): ?><div class="alert alert-danger"><ul class="mb-0"><?php foreach($errors as $err): ?><li><?=e($err)?></li><?php endforeach; ?></ul></div><?php endif; ?><form method="post" class="needs-validation" novalidate><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="mb-3"><label class="form-label">اسم المستخدم</label><input class="form-control" name="username" required minlength="3" maxlength="100" value="<?=e($username)?>"><div class="invalid-feedback">أدخل اسم مستخدم من 3 محارف على الأقل.</div></div><div class="mb-3"><label class="form-label">البريد الإلكتروني</label><input type="email" class="form-control" name="email" required maxlength="100" value="<?=e($email)?>"><div class="invalid-feedback">أدخل بريداً صحيحاً.</div></div><div class="mb-3"><label class="form-label">كلمة المرور</label><input type="password" class="form-control" name="password" required minlength="8" autocomplete="new-password"><div class="form-text">8 محارف على الأقل.</div></div><div class="mb-3"><label class="form-label">تأكيد كلمة المرور</label><input type="password" class="form-control" name="confirm_password" required minlength="8" data-match="password" autocomplete="new-password"></div><button class="btn btn-primary w-100">إنشاء الحساب</button></form><p class="mt-3 mb-0">لديك حساب؟ <a href="<?=BASE_URL?>/login.php">سجّل الدخول</a></p></div><?php require __DIR__.'/inc/footer.php'; ?>